node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
const S=rd("test/e2e/surfaces.ts")
if(S===null)fail("test/e2e/surfaces.ts is gone")
const L=S.split("\n")
const gs=L.findIndex((l)=>l.includes("GLOBAL_MASK_SELECTORS: readonly"))
if(gs<0)fail("GLOBAL_MASK_SELECTORS is gone, so nothing applies any mask at all")
const ge=L.findIndex((l,i)=>i>gs && l.trim()==="]")
if(ge<0)fail("could not find the end of GLOBAL_MASK_SELECTORS, so this arm cannot measure anything")
if(!L.slice(gs,ge).join("\n").includes("[data-visual-mask]"))fail("GLOBAL_MASK_SELECTORS no longer applies [data-visual-mask], so every registered mask paints nothing and the registry is decorative")
for(const v of ["admin-rail","admin-kpis"]){if(!new RegExp("value: .?"+v+"[^\\w-]").test(S))fail(v+" is not registered in VISUAL_MASK_SITES")}
const R=rd("components/frequency/admin/admin-nav.tsx")
if(R===null)fail("the admin rail column component is gone")
if(!/data-visual-mask="admin-rail"/.test(R))fail("the operator info rail is unmasked again: one member joining reds out four blocking admin baselines")
const A=rd("app/(main)/admin/page.tsx")
if(A===null)fail("the admin dashboard page is gone")
if(!/data-visual-mask="admin-kpis"/.test(A))fail("the /admin header KPIs are unmasked again, which is the extra diff that made /admin differ from its three siblings")
console.log("ok")'
